'use strict';
document.querySelector('#test').addEventListener('click',async()=>{const el=document.querySelector('#result'),b=document.querySelector('#test');b.disabled=true;try{const response=await fetch('../examples/upload-fixtures/synthetic-scan.pdf');const doc=await PlanningFiles.extract(new File([await response.arrayBuffer()],'synthetic-scan.pdf'),{ocrMode:'auto',progress:m=>el.textContent=m});el.textContent=JSON.stringify({pages:doc.pages.length,blocks:doc.blocks.length,issues:doc.issues,lines:doc.blocks.map(x=>({text:x.text,confidence:x.confidence,uncertain:x.uncertain,bbox:x.bbox}))},null,2);if(doc.blocks.some(x=>x.method==='ocr')&&!localStorage.getItem('project-factory-planning-v03')){let material=PlanningFiles.attach({},doc,doc.blocks[0]);material.kind='sample';material.period='가상 시험 자료';const state={version:'0.7.0',selected:['hotel-housekeeping'],common:{title:'가상 스캔 OCR 시험 — 실제 근거 아님'},answers:{},checks:[],references:{},materials:{'E-hotel-housekeeping-1':material},imports:[doc]};localStorage.setItem('project-factory-planning-v03',JSON.stringify(state));el.textContent+='\n기획 작성 화면에 가상 시험 결과를 저장했습니다.';}}catch(e){el.textContent='실패: '+e.message;}finally{b.disabled=false;}});
